"""Three canon-based sect plans. One native call each; preserve original outputs."""
import json, sys, shutil, hashlib, re
from pathlib import Path
import yaml
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'assets/raw/sect_remaining_designs_20261029l'
QUEUE=ROOT/'assets/staging/sect_remaining_designs_20261029l/production'
COMMON='''Create a highly refined landscape full-site architectural concept masterplan for a Chinese wuxia 2.5D RPG. A single coherent settlement viewed from elevated parallel three-quarter game camera, realistic hand-painted materials, readable fine detail, no photorealistic camera blur. Keep whole site, roofs and approach inside frame. This is a construction reference, NOT a flat playable background. Architecture must rest on continuous terrain: visible retaining faces and connected terraces, stairs joining actual lower and upper landing surfaces, no ornamental stairs on flat ground. Walkable routes must connect every courtyard doorway. Boundary walls join corners and gate posts, never loose stubs. Buildings vary greatly in width, footprint and storey count while adult door scale stays consistent: dominant hall, medium shared hall, narrow multi-storey residence, low service house, tiny storage shed. Courtyard groups, not evenly spaced rows of identical houses. Show a readable main approach and a separate practical return/service route. Tiny ordinary people provide scale only, no identifiable new named character, no plot events or rewards. Opaque illustration with clear daylight and restrained distant atmospheric haze; no clouds hiding stairs or junctions, no giant decorative waterfalls, no UI. Include only the six short Chinese numbered zone labels specified, in elegant small legible text away from roads. No other captions. Material transitions must follow use: worn stone steps, compacted earth service paths, stone practice courts. Distinguish ceremonial, training and domestic areas without excessive ornament. Landscape 3:2 composition.
'''
SPECS={
'huashan':COMMON+'''HUASHAN sect: a severe soaring GRANITE RIDGE sword school, pale cold granite and slate-grey tiled roofs with muted reddish-brown timber. Distinctive long narrow diagonal ridge silhouette rather than a symmetrical Daoist palace. Six zones: 01 山门石径; 02 练剑前坪; 03 主堂剑院; 04 弟子居舍; 05 论剑台; 06 思过崖. A zigzag lower entry climbs a real stair to a middle spacious sword-practice court; a second supported stair reaches the highest substantial main hall courtyard. The broad practice court fits several sparring pairs; modest weapon racks only at its edge. West-side medium dormitory group, kitchen and small shed share a sheltered domestic terrace with a continuous narrow return path to the practice court, not scattered scenic pavilions. On the east, a short anchored parapeted stone path reaches a compact exposed discussion platform. A clearly connected cliff-side footpath reaches a small bare reflection ledge, not an isolated floating island or inaccessible cliff opening. Three visible ground levels and two principal stair landings, with continuous rock shoulders. Slender sparse mountain pines; avoid turquoise Wudang roofs, taiji symbols, pagodas and huge bridges. Main hall 4 times footprint of small houses, not all identical temples. Compose architecture as an inhabited coherent small compound on a dangerous ridge, keeping generous playable clearances.''',
'gufeng':COMMON+'''GUFENG sect on GUYUE PEAK, a rugged mountain blade-and-strength school. Distinctive WARM OCHRE GREY RUBBLE-STONE stockade and thick weathered brown timber, rough low slate or timber roofs, dry mountain grasses and broad stony hillside; NOT red desert mudbrick, NOT elegant palace buildings. Six zones: 01 石寨山门; 02 演武石坪; 03 聚义大堂; 04 弟子石舍; 05 烧酒工坊; 06 后山练力. The settlement occupies a wide horseshoe-shaped mountain bowl. A continuous irregular defensive stone boundary follows natural rock shoulders and connects to a robust gatehouse; leave a genuine open gate threshold. Lower gate yard connects by broad shallow stair to a central large packed-earth and irregular stone training court, then another short stair to the great hall on a modest rear rock plinth. Great hall is a wide low heavy-beam structure, dwellings include a narrow two-storey stone house and tiny flat-roof stores, making the silhouette varied. A separate practical freight loop runs from gate around west domestic court to the brewing workyard with restrained barrels, water vats and firewood; never force deliveries through sparring space. Rear strength-training terrace has human-sized timber posts and lifting stones, connected to the upper hall and side loop. Three moderate actual elevations supported by continuous rubble retaining walls; stairs exactly bridge differences, no gigantic cliffs or showy waterfall. A few rough handrails, no skulls, torture imagery, villain fortress, huge decorative blades or invented religious icons. Warm sturdy lived-in communal mountain fortress.''',
'lingyue':COMMON+'''LINGYUE sect: cool luminous BAMBOO LODGE compounds surrounding a small mountain pool, associated with light footwork and LONG STAFF training. Moon-white plaster accents, pale weathered bamboo and silver-grey roof tiles, subdued lilac cloth awnings used sparingly. Clean soft cool DAYLIGHT, not dark blue night. Six zones: 01 竹径山门; 02 演棍坪; 03 临潭主楼; 04 弟子竹舍; 05 月潭曲桥; 06 后山静台. Strong open crescent composition around a SMALL pool occupying no more than one sixth of land area; not a palace island, broad river, waterfall or romantic resort. A low south bamboo gate opens to a spacious dry stone STAFF practice court, long staffs stacked at edge and a few tiny ordinary practitioners including women and men for scale. A broad asymmetric two-storey timber-bamboo main lodge on the north bank dominates medium dormitory court and smaller kitchen/store sheds; stair to upper terrace has real retaining face, landing and doorway. Low bamboo fences enclose domestic courts connected to building corners. Two short low bridges span NARROW pool-inlet channels and land on wide paths at matching height; a longer curving bank walkway follows solid shore, not randomly floating boards. A bamboo-grove back path loops behind the modest elevated meditation terrace and joins dormitories, leaving public practice yard clear. Three modest terrain levels, clear functional stairs, actual support columns under raised bamboo floors. Bamboo and pale rock outcrops make atmosphere distinct from pine-granite Huashan and ochre stone Gufeng. No swords as primary training weapon, no lotus palace, no pagoda cluster, no identical-size pavilions.'''
}
NAMES={'huashan':'华山派 · 险峰剑院总规','gufeng':'古峰派 · 山野石寨总规','lingyue':'凌月派 · 寒潭竹楼总规'}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n','utf-8')
def prepare():
    assert not BASE.exists();BASE.mkdir(parents=True);(QUEUE/'templates').mkdir(parents=True)
    (QUEUE/'templates/design.yaml').write_text(yaml.safe_dump({'prompt_template':'{asset_prompt}','size':'1536x1024','quality':'high','background':'opaque'}),'utf-8')
    import gen_assets as renderer
    renderer.TEMPLATES_DIR=QUEUE/'templates'; rows=[]
    for key,prompt in SPECS.items():
        assert renderer.render_template('design',{'asset_prompt':prompt},{})['prompt']==prompt.strip()
        p=QUEUE/(key+'.txt');p.write_text(prompt,'utf-8')
        rows.append({'key':key,'name':NAMES[key],'id':'sect_remaining_20261029l_'+key,'prompt':p.relative_to(ROOT).as_posix(),'prompt_sha256':sha(p),'calls':0,'status':'REGISTERED','backend':'builtin_image_gen','model':None,'provider':None,'cost':None,'fallback_used':False,'game_consumers':0})
    save(BASE/'manifest.json',{'assets':rows,'scope':'new sect design candidates; no runtime consumers'})
    (QUEUE/'tasks.yaml').write_text(yaml.safe_dump({'tasks':[{'id':r['id'],'skip':True,'execution_backend':'builtin_image_gen','attempt_budget':1,'retries_allowed':False,'cli_fallback_allowed':False} for r in rows]}),'utf-8')
    save(BASE/'preflight.json',{'actual_renderer_passed':True,'tasks':3,'root_queue_changed':False})
def start(key):
    m=json.loads((BASE/'manifest.json').read_text('utf-8'));r=next(r for r in m['assets'] if r['key']==key);assert r['calls']==0
    r.update(calls=1,status='DISPATCHED');save(BASE/'manifest.json',m)
def record(key,source):
    m=json.loads((BASE/'manifest.json').read_text('utf-8'));r=next(r for r in m['assets'] if r['key']==key);assert r['status']=='DISPATCHED'
    src=Path(source);dst=BASE/(key+'_masterplan_v1.png');assert not dst.exists();shutil.copyfile(src,dst);assert sha(src)==sha(dst)
    with Image.open(dst) as im:r.update(size=list(im.size),mode=im.mode)
    r.update(status='DESIGN_CANDIDATE',output=dst.relative_to(ROOT).as_posix(),sha256=sha(dst),source_path=str(src));save(BASE/'manifest.json',m)
def finish():
    m=json.loads((BASE/'manifest.json').read_text('utf-8'))
    for r in m['assets']:assert r['status']=='DESIGN_CANDIDATE' and sha(ROOT/r['output'])==r['sha256'] and r['calls']==1
    m['items']={r['key']:r for r in m['assets']};save(BASE/'manifest.json',m)
    p=json.loads(re.search(r'<script id="catalogData" type="application/json">([\s\S]*?)</script>',(ROOT/'docs/equipment-skill-catalog.html').read_text('utf-8'))[1])
    save(BASE/'catalog-nonresources-before.json',{k:v for k,v in p.items() if k!='resources'})
if __name__=='__main__':{'prepare':prepare,'start':lambda:start(sys.argv[2]),'record':lambda:record(sys.argv[2],sys.argv[3]),'finish':finish}[sys.argv[1]]()
